/**
 * Exports service — CSV export of transactions (API_CONTRACT.md §8).
 *
 * Endpoint:
 *   GET /api/v1/exports/transactions.csv   exportTransactionsCsv
 *
 * Query parameters: book_id, type, category_id, payment_method_id, date_from,
 * date_to, search.  There is no `ordering` or `page` (the full filtered result
 * set is returned with a fixed ordering).  The CSV is generated by the backend;
 * this module only fetches the text and the server-suggested filename.
 *
 * Request notes:
 *  - The client's default `Accept: application/json` is kept on purpose: the
 *    view is a DRF APIView, so asking for `text/csv` would fail content
 *    negotiation (406).
 *  - `responseType` is deliberately left unset.  Axios then returns the CSV as
 *    a string (JSON parsing fails silently on CSV text) while a JSON error
 *    envelope (400/401) is parsed into an object, which lets the shared
 *    response interceptor normalise failures exactly like every other call.
 */

import apiClient from './client'
import { buildTransactionFilterQuery } from './transactionQuery'
import type { ApiError, TransactionExportParams } from '@/types'

const EXPORT_URL = '/api/v1/exports/transactions.csv'

export const DEFAULT_EXPORT_FILENAME = 'transactions.csv'

export interface CsvDownload {
  blob: Blob
  filename: string
}

/**
 * Extract a safe filename from a Content-Disposition header.  Falls back to the
 * contract's default when the header is absent (e.g. not exposed by CORS), has no
 * filename, or the filename is not a plain `.csv` name.
 */
export function parseContentDispositionFilename(header: unknown): string {
  if (typeof header !== 'string') return DEFAULT_EXPORT_FILENAME
  const match = /filename\*?=(?:UTF-8'')?"?([^";]+)"?/i.exec(header)
  const candidate = match?.[1]?.trim()
  if (!candidate || !/^[\w.\- ]+\.csv$/i.test(candidate)) {
    return DEFAULT_EXPORT_FILENAME
  }
  return candidate
}

/** Fetch the filtered transactions CSV as a Blob plus its filename. */
export async function exportTransactionsCsv(
  params: TransactionExportParams = {},
  signal?: AbortSignal,
): Promise<CsvDownload> {
  const response = await apiClient.get<unknown>(EXPORT_URL, {
    params: buildTransactionFilterQuery(params),
    signal,
  })
  if (typeof response.data !== 'string') {
    const unexpected: ApiError = {
      error: { code: 'server_error', message: 'The export returned an unexpected response.' },
    }
    throw unexpected
  }
  const headers = response.headers as Record<string, unknown> | undefined
  return {
    blob: new Blob([response.data], { type: 'text/csv;charset=utf-8' }),
    filename: parseContentDispositionFilename(headers?.['content-disposition']),
  }
}
